import CONSTANTS from "redux/constants";

export const socketReducer = (
  state = {
    connected: false,
    connecting: true,
    socket: null,
    curChatUser: {
      username: "",
      firstname: "",
      lastname: "",
      middlename: "",
      gender: "",
      id: "",
      email: "",
      onlineStatus: "Offline",
    },
    call: {
      currentCall: false,
      callUser: null,
      sound: null,
      status: "",
      from: null,
      to: null,
      peer: null,
      localStream: null,
      remoteStream: null,
      rtcMessage: null,
      isInitiator: null,
      showModal: false,
      reference: null,
      start: null,
      duration: "",
      totalTime: 0,
    },
    histories: [],
    rosters: [],
  },
  action
) => {
  switch (action.type) {
    case CONSTANTS.SOCKET_CONNECT:
      return {
        ...state,
        socket: action.payload.socket,
        connected: true,
        connecting: false,
      };
    case CONSTANTS.SOCKET_STATUS:
      return {
        ...state,
        connected: action.payload.connected,
        connecting: action.payload.connecting,
      };
    case CONSTANTS.SOCKET_DISCONNECT:
      return { ...state, socket: null, connected: false, connecting: false };
    case CONSTANTS.SOCKET_RECONNECT:
      return {
        ...state,
        socket: action.payload,
        connected: true,
        connecting: false,
      };
    case CONSTANTS.SOCKET_RECONNECTING:
      return { ...state, socket: null, connected: false, connecting: true };
    case CONSTANTS.SOCKET_RECONNECT_ERROR:
      return { ...state, socket: null, connected: false, connecting: false };
    case CONSTANTS.SOCKET_RECONNECT_FAILED:
      return { ...state, socket: null, connected: false, connecting: false };
    case CONSTANTS.SOCKET_ERROR:
      return { ...state, socket: null, connected: false, connecting: false };
    case CONSTANTS.SET_CHAT_USER:
      // const loggedInUser = JSON.parse(localStorage.getItem("loggedInUser"));
      const rosterUpdate = state.rosters.map((roster) => {
        if (roster._id == action.payload.id) {
          // findinig the user in the roster
          if (
            roster?.lastMessage?.sender ||
            roster?.lastMessage?.from == action.payload._id
          ) {
            return {
              ...roster,
              lastMessage: {
                ...roster?.lastMessage,
                seen: Date.now(),
              },
            };
          }
        }
        return roster;
      });
      return {
        ...state,
        curChatUser: {
          ...state.curChatUser,
          username: action.payload.username,
          firstname: action.payload.firstname,
          lastname: action.payload.lastname,
          middlename: action.payload.middlename,
          gender: action.payload.gender,
          id: action.payload.id,
          email: action.payload.email,
          onlineStatus: action.payload.onlineStatus || "Offline",
        },
        rosters: rosterUpdate,
      };
    case CONSTANTS.RETRIEVE_HISTORY:
      return { ...state, histories: action.payload };
    case CONSTANTS.RECEIVE_MESSAGE:
      // console.log("action.payload", action.payload.from);
      if (
        action.payload.from ||
        action.payload.sender == state.curChatUser.id
      ) {
        return {
          ...state,
          curChatUser: { ...state.curChatUser, onlineStatus: "Online" },
          histories: [...state.histories, action.payload],
        };
      }
      return state;
    case CONSTANTS.SEND_MESSAGE:
      const newRosters = state.rosters.map((roster) => {
        if (roster._id === action.payload.to) {
          return { ...roster, lastMessage: action.payload };
        } else {
          return roster;
        }
      });
      return {
        ...state,
        histories: [...state.histories, action.payload],
        rosters: newRosters,
      };
    case CONSTANTS.GET_ROSTER:
      return { ...state, rosters: action.payload.rosters };
    case CONSTANTS.ADD_ROSTER:
      return { ...state, histories: [...state.rosters, action.payload] };
    case CONSTANTS.SET_CALL:
      return {
        ...state,
        call: { ...state.call, ...action.payload },
      };
    case CONSTANTS.SET_CALL_MODAL:
      return {
        ...state,
        call: { ...state.call, showModal: action.payload },
      };
    case CONSTANTS.SET_CALL_DURATION:
      return {
        ...state,
        call: {
          ...state.call,
          duration: action.payload.duration,
          totalTime: action.payload.totalTime,
        },
      };
    default:
      return state;
  }
};
