import React, { useState, useEffect } from "react";
import { useLocation, Switch, Redirect, Route } from "react-router-dom";
import AdminNavbar from "components/Navbars/AdminNavbar";
import Footer from "components/Footer/Footer";
import Sidebar from "components/Sidebar/Sidebar";
import { Modal, Card, Form, Row, Col } from "react-bootstrap";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faPhone, faTimes } from "@fortawesome/fontawesome-free-solid";
import routes from "routes.js";
import sidebarImage from "assets/img/sidebar-3.jpg";
import AddUser from "views/AddUser";
import EditUser from "views/EditUser";
import NotFound from "views/NotFound";
import AddAgeGroup from "views/Data/AgeGroup/AddAgeGroup";

// livekit imports
import {
  createLocalVideoTrack,
  LocalVideoTrack,
  createLocalTracks,
  RemoteParticipant,
  RemoteTrackPublication,
  RemoteTrack,
  Room,
  RoomEvent,
  setLogLevel,
  VideoPresets,
} from "livekit-client";
// chat required imports
import { connect } from "react-redux";

import EditAgeGroup from "views/Data/AgeGroup/EditAgeGroup";
import AddCallType from "views/Data/CallType/AddCallType";
import EditCallType from "views/Data/CallType/EditCallType";
import AddShift from "views/Data/Shift/AddShift";
import EditShift from "views/Data/Shift/EditShift";
import AddRole from "views/Data/Roles/AddRole";
import EditRole from "views/Data/Roles/EditRole";

import CustomizedButton from "components/common/CustomizedButton";
import { isSelected } from "helpers/array.helper";
import { socketConnect } from "redux/action/socket";

import BlogAdd from "views/Blog/BlogAdd";
import BlogEdit from "views/Blog/BlogEdit";
import { stopTimer } from "redux/action/socket";
import { getFirstLetter } from "helpers";
import { occupation } from "Data/formOptions";
import { maritalStatus } from "Data/formOptions";
import { vulnerability } from "Data/formOptions";
import { callType } from "Data/formOptions";
import { sucide } from "Data/formOptions";
import { services } from "Data/formOptions";
import { referralTo } from "Data/formOptions";
import { referralsFrom } from "Data/formOptions";
import { callers } from "Data/formOptions";
import { supportThrough } from "Data/formOptions";
import useFetchData from "hooks/useFetchData";
import { axios } from "utility/httpreq";

// chat required imports
let defaultForm = {
  facilitator: "",
  customerUserName: "",
  callFrom: "",
  firstname: "",
  middlename: "",
  lastname: "",
  address: "",
  province: "",
  email: "",
  phone: "",
  gender: "",
  ageGroup: "",
  shift: "",
  callType: "",
};

const callStatus = {
  incoming: "incoming",
  outgoing: "outgoing",
  disconnected: "disconnected",
  connected: "connected",
  connecting: "connecting",
};
function AdminLayout(props) {
  // console.log(document.getElementById('outgoingCall'))
  const user = JSON.parse(localStorage.getItem("loggedInUser"));
  const [image, setImage] = React.useState(sidebarImage);
  const [color, setColor] = React.useState("white");

  const [showModal, setShowModal] = React.useState(false);
  const [hasImage, setHasImage] = React.useState(true);
  const [loading, setLoading] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const location = useLocation();
  const mainPanel = React.useRef(null);

  const [call, setCall] = useState({
    user: null,
    status: "",
    roomToken: null,
    from: null,
    to: null,
    showModal: false,
  });
  const [room, setRoom] = useState(null);
  const [myTrack, setMyTrack] = useState(null);
  const [mute, setMute] = useState(myTrack?.isMuted || false);

  useEffect(() => {
    if (myTrack) {
      setMute(myTrack?.isMuted);
      myTrack.on("muted", () => {
        setMute(true);
      });

      myTrack.on("unmuted", () => {
        setMute(false);
      });
    }
  }, [myTrack]);
  const muteMic = async () => {
    if (myTrack.isMuted) {
      await myTrack?.unmute(true);
    } else {
      await myTrack?.mute(false);
    }
  };
  //livekit
  const callConnect = async (token) => {
    try {
      const track = await createLocalTracks({
        audio: true,
        // video: true,
      });
      let url = process.env.REACT_APP_LIVEKIT_URL;
      const params = {
        adaptiveStream: true,
      };

      params.token = token;
      const room = new Room(params);
      setRoom(room);
      // setting video and audio

      await room.connect(url, token);
      const localTrack = await room.localParticipant.publishTrack(track[0], {
        priority: "high",
        name: "audioTrackSE",
      });
      setMyTrack(localTrack);
      // await room.localParticipant.setMicrophoneEnabled(true);
    } catch (err) {
      console.log("error is ", err);
    }
  };

  const callDisconnect = () => {
    room?.disconnect();
    setCall({
      ...call,
      status: callStatus.disconnected,
    });
  };

  useEffect(() => {
    if (room) {
      // if call is incoming then set status to connecting since I just clicked ont he accept button it takes time to connect
      if (call.status === callStatus.incoming) {
        setCall({
          ...call,
          status: callStatus.connecting,
        });
      }

      room.on(RoomEvent.ParticipantConnected, (participant) => {
        setCall({
          ...call,
          status: callStatus.connected,
        });
      });
      room.on(RoomEvent.ParticipantDisconnected, (participant) => {
        setCall({
          ...call,
          status: callStatus.disconnected,
        });
      });

      function handleTrackSubscribed(track) {
        // attach video if required
        track.attach();
        // videoRef?.current?.appendChild(track.attach());
      }

      room.on(RoomEvent.TrackSubscribed, handleTrackSubscribed);
      room.on(RoomEvent.Disconnected, () => {
        setCall({
          ...call,
          status: callStatus.disconnected,
        });
      });

      room.on(RoomEvent.Connected, () => {
        // if call is incoming and I am connected then set status to connected since another user is already connected
        if (call.status === "incoming") {
          setCall({
            ...call,
            status: callStatus.connected,
          });
        }

        // if call is outgoing and I am connected then set status to connecting since another participant is not connected
        if (call.status === "outgoing") {
          setCall({
            ...call,
            status: callStatus.connecting,
          });
        }
      });
    }
  }, [room]);

  //Chat Required Stuff
  const [formData, setFormData] = useState({
    ...defaultForm,
    firstname: props?.io?.call?.callUser?.firstname || "",
    lastname: props?.io?.call?.callUser?.lastname || "",
    middlename: props?.io?.call?.callUser?.middlename || "",
    gender: props?.io?.call?.callUser?.gender || "",
  });

  const data = useFetchData("/api/call-log/data")?.data;

  const getBrandText = () => {
    for (let i = 0; i < routes.length; i++) {
      if (location.pathname.indexOf(routes[i].layout + routes[i].path) > -1) {
        return routes[i].name;
      }
    }

    return location.pathname.split("/").pop();
  };

  React.useEffect(() => {
    document.documentElement.scrollTop = 0;
    document.scrollingElement.scrollTop = 0;
    mainPanel.current.scrollTop = 0;
    if (
      window.innerWidth < 993 &&
      document.documentElement.className.indexOf("nav-open") !== -1
    ) {
      document.documentElement.classList.toggle("nav-open");
      var element = document.getElementById("bodyClick");
      element.parentNode.removeChild(element);
    }
  }, [location]);

  const loggedInUser = localStorage.getItem("loggedInUser");
  // Chat and Call codes

  useEffect(() => {
    if (!props.io.connected) {
      props.socketConnect();
    } else {
      props?.io?.socket?.on("initCallToken", (data) => {
        if (data.token) {
          callConnect(data.token);
        }
      });
      // when someone is calling me
      props?.io?.socket?.on("newCall", (data) => {
        console.log("incoming call ", data);
        setCall({
          ...call,
          user: data.senderDetail,
          status: callStatus.incoming,
          roomToken: data.token,
          showModal: true,
        });
      });
    }
  }, [props.io.connected]);

  const acceptCall = () => {
    if (call.roomToken) {
      callConnect(call.roomToken);
    }
  };
  const handleChange = (e) => {
    const { value, name } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const getRoutes = (routes) => {
    return routes.map((prop, key) => {
      if (prop.layout === "/admin") {
        return (
          <Route
            path={prop.layout + prop.path}
            render={(props) => {
              if (prop.path == "/chat") {
                props.setCall = setCall;
                props.call = call;
              }
              return <prop.component {...props} />;
            }}
            key={key}
            exact
          />
        );
      }
    });
  };

  const getPhoneButton = (data) => {
    let content;
    content = (
      <button
        type="button"
        onClick={() => {
          acceptCall();
        }}
        className="mr-3 ml-3 btn-circle btn-start-call d-md-inline-block btn"
      >
        <FontAwesomeIcon icon={faPhone} />
      </button>
    );

    return content;
  };

  const getMuteButton = (data) => {
    let content;
    // if call is connected send mute button
    if (data.status === "connected") {
      content = (
        <button
          className={`mr-3 ml-3 btn-circle d-md-inline-block btn btn-mute-off ${
            mute ? "btn-mute" : ""
          }`}
          onClick={() => {
            muteMic();
          }}
        >
          <i className="nc-icon nc-audio-92"></i>
        </button>
      );
    }
    return content;
  };

  const getDeclineButton = (data) => {
    let content;
    if (data.status != "disconnected") {
      content = (
        <button
          type="button"
          onClick={() => {
            callDisconnect();
          }}
          className="mr-3 ml-3 btn-circle btn-end-call d-md-inline-block btn"
        >
          {/* <FontAwesomeIcon icon="fas fa-phone-alt" /> */}
          <FontAwesomeIcon icon={faTimes} />
        </button>
      );
    }
    return content;
  };

  const handleCloseModal = (type) => {
    if (type === "yes") {
      props?.setCallModal(false);
      // window.location.reload();
    }
    setShowModal(false);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      setIsSubmitting(true);
      await axios(true).post("/api/call-log/add", {
        ...formData,
        callFrom: props?.io?.call?.isInitiator ? "facilitator" : "participant",
        facilitator: user?._id,
        customerUserName: props?.io?.call?.callUser?.username,
        duration: props?.io?.call?.duration,
        totalTime: props?.io?.call?.totalTime,
        callStartDate: props?.io?.call?.callStartDate,
      });
      setIsSubmitting(false);
    } catch (err) {
      setIsSubmitting(false);
      console.log("error is", err);
    }
  };
  return (
    <>
      <div className="wrapper">
        <Sidebar color={color} image={hasImage ? image : ""} routes={routes} />
        <div className="main-panel" ref={mainPanel}>
          <AdminNavbar />
          <div className="content" id={getBrandText()}>
            {loggedInUser ? (
              <>
                <Switch>
                  {getRoutes(routes)}
                  <Route
                    exact
                    path={"/admin/user/add"}
                    component={AddUser}
                  ></Route>{" "}
                  <Route
                    exact
                    path={"/admin/user/edit/:id"}
                    component={EditUser}
                  ></Route>
                  {/* cage group */}
                  <Route
                    exact
                    path={"/admin/agegroup/add"}
                    component={AddAgeGroup}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/agegroup/edit/:id"}
                    component={EditAgeGroup}
                  ></Route>
                  {/* Call type Route */}
                  <Route
                    exact
                    path={"/admin/calltype/add"}
                    component={AddCallType}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/calltype/edit/:id"}
                    component={EditCallType}
                  ></Route>
                  {/* Shift Route */}
                  <Route
                    exact
                    path={"/admin/shift/add"}
                    component={AddShift}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/shift/edit/:id"}
                    component={EditShift}
                  ></Route>
                  {/* Role Route */}
                  <Route
                    exact
                    path={"/admin/role/add"}
                    component={AddRole}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/role/edit/:id"}
                    component={EditRole}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/blogs/add"}
                    component={BlogAdd}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/blogs/edit/:id"}
                    component={BlogEdit}
                  ></Route>
                  <Route component={NotFound}></Route>
                </Switch>
              </>
            ) : (
              <>
                <Switch>
                  <Redirect to="/auth/login" />
                </Switch>
              </>
            )}
          </div>
          <Footer />
        </div>
      </div>

      {/* Mini Modal */}
      <Modal
        className="modal-mini modal-primary call-modal"
        show={call?.showModal}
        // onHide={() => {
        //   setCall({
        //     ...call,
        //     showModal: false,
        //   });
        // }}
        backdrop="static"
      >
        <Modal.Body className="d-flex p-0">
          <div className="voice-call-page call-wrapper">
            <div className="call-header">
              <p className="font-weight-bold"> {call.status} </p>
            </div>
            <div className="d-flex align-items-center py-1 flex-column call-body">
              <div className="position-relative">
                <div className="avatar-box bg-light-danger">
                  <span className="avatar-label">
                    {getFirstLetter(call?.user?.username)}
                  </span>
                </div>
              </div>
              <div className="flex-grow-1">
                <span className="chat-username-sm">{call?.user?.username}</span>
                <div className="text-muted small text-center">
                  <strong> Duration </strong>
                </div>
              </div>
            </div>

            <div className="call-control-btns d-flex justify-content-center align-items-center w-100">
              {getPhoneButton()}
              {getDeclineButton(call)}
              {getMuteButton(call)}
            </div>
          </div>
          <Row>
            <Col md="12">
              <Card>
                <Card.Header className="d-flex justify-content-between">
                  <Card.Title as="h4"> Service Seeker Information </Card.Title>

                  <button
                    onClick={() => {
                      setShowModal(true);
                    }}
                    className="close"
                  >
                    <i className="nc-icon nc-simple-remove"></i>
                  </button>
                </Card.Header>

                <Card.Body>
                  {loading ? (
                    "loading..."
                  ) : (
                    <Form onSubmit={handleSubmit}>
                      <Row>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label>First Name</label>
                            <Form.Control
                              placeholder="First Name"
                              type="text"
                              name="firstname"
                              value={formData?.firstname}
                              onChange={handleChange}
                              required
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label>Middle Name</label>
                            <Form.Control
                              placeholder="Middle Name"
                              type="text"
                              name="middlename"
                              value={formData?.middlename}
                              onChange={handleChange}
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label>Last Name</label>
                            <Form.Control
                              placeholder="Last Name"
                              type="text"
                              name="lastname"
                              value={formData?.lastname}
                              onChange={handleChange}
                              required
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                      </Row>
                      <Row>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label> Age </label>
                            <Form.Control
                              placeholder="age"
                              onChange={handleChange}
                              value={formData.age}
                              type="text"
                              name="age"
                            ></Form.Control>
                          </Form.Group>
                        </Col>

                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Sex</label>
                            <select
                              required
                              name="gender"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              <option
                                selected={isSelected("Male", formData.gender)}
                                value="Male"
                              >
                                Male{" "}
                              </option>
                              <option
                                selected={isSelected("Female", formData.gender)}
                                value="Female"
                              >
                                Female{" "}
                              </option>
                              <option
                                selected={isSelected("Other", formData.gender)}
                                value="Other"
                              >
                                Other{" "}
                              </option>
                            </select>
                          </Form.Group>
                        </Col>

                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label> Address </label>
                            <Form.Control
                              placeholder="Address"
                              onChange={handleChange}
                              value={formData.address}
                              type="text"
                              name="address"
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                      </Row>

                      <Row>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Occupation</label>
                            <select
                              required
                              name="occupation"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {Object.keys(occupation).map((key) => {
                                return (
                                  <option
                                    selected={isSelected(
                                      occupation[key],
                                      formData?.occupation
                                    )}
                                    value={occupation[key]}
                                  >
                                    {occupation[key]}
                                  </option>
                                );
                              })}
                              <option
                                selected={isSelected("Doctor", formData.gender)}
                                value="Male"
                              >
                                Doctor{" "}
                              </option>
                            </select>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Marital Status</label>
                            <select
                              required
                              name="maritalStatus"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {Object.keys(maritalStatus).map((key) => {
                                return (
                                  <option
                                    selected={isSelected(
                                      maritalStatus[key],
                                      formData?.maritalStatus
                                    )}
                                    value={maritalStatus[key]}
                                  >
                                    {maritalStatus[key]}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Vulnerability</label>
                            <select
                              required
                              name="vulnerability"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {Object.keys(vulnerability).map((key) => {
                                return (
                                  <option
                                    selected={isSelected(
                                      vulnerability[key],
                                      formData?.vulnerability
                                    )}
                                    value={vulnerability[key]}
                                  >
                                    {vulnerability[key]}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                      </Row>
                      <Row>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Call Type</label>
                            <select
                              required
                              name="callType"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {Object.keys(callType).map((key) => {
                                return (
                                  <option
                                    selected={isSelected(
                                      callType[key],
                                      formData?.callType
                                    )}
                                    value={callType[key]}
                                  >
                                    {callType[key]}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Sucide</label>
                            <select
                              required
                              name="sucide"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {Object.keys(sucide).map((key) => {
                                return (
                                  <option
                                    selected={isSelected(
                                      sucide[key],
                                      formData?.sucide
                                    )}
                                    value={sucide[key]}
                                  >
                                    {sucide[key]}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                      </Row>
                      <Row>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label htmlFor="exampleInputPhone">Phone</label>
                            <Form.Control
                              placeholder="Phone"
                              onChange={handleChange}
                              value={formData.phone}
                              type="text"
                              name="phone"
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label htmlFor="exampleInputPhone">
                              Significant Others
                            </label>
                            <Form.Control
                              placeholder="Phone of significant others"
                              onChange={handleChange}
                              value={formData.phoneOfSignificantOther}
                              type="text"
                              name="phoneOfSignificantOther"
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label htmlFor="exampleInputPhone">Relation</label>
                            <Form.Control
                              placeholder="Relation"
                              onChange={handleChange}
                              value={formData.relation}
                              type="text"
                              name="relation"
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                      </Row>
                      <Row>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Services</label>
                            <select
                              required
                              name="service"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {Object.keys(services).map((key) => {
                                return (
                                  <option
                                    selected={isSelected(
                                      services[key],
                                      formData?.service
                                    )}
                                    value={services[key]}
                                  >
                                    {services[key]}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Referrals To</label>
                            <select
                              required
                              name="referralTo"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {Object.keys(referralTo).map((key) => {
                                return (
                                  <option
                                    selected={isSelected(
                                      referralTo[key],
                                      formData?.referralTo
                                    )}
                                    value={referralTo[key]}
                                  >
                                    {referralTo[key]}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Referrals From</label>
                            <select
                              required
                              name="referralFrom"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {Object.keys(referralsFrom).map((key) => {
                                return (
                                  <option
                                    selected={isSelected(
                                      referralsFrom[key],
                                      formData?.referralsFrom
                                    )}
                                    value={referralsFrom[key]}
                                  >
                                    {referralsFrom[key]}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                      </Row>

                      <Row>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Callers</label>
                            <select
                              required
                              name="caller"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {Object.keys(callers).map((key) => {
                                return (
                                  <option
                                    selected={isSelected(
                                      callers[key],
                                      formData?.caller
                                    )}
                                    value={callers[key]}
                                  >
                                    {callers[key]}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Support Through</label>
                            <select
                              required
                              name="supportThrough"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {Object.keys(supportThrough).map((key) => {
                                return (
                                  <option
                                    selected={isSelected(
                                      supportThrough[key],
                                      formData?.supportThrough
                                    )}
                                    value={supportThrough[key]}
                                  >
                                    {supportThrough[key]}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Shift</label>
                            <select
                              // required
                              name="shift"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {data?.shifts?.map((shift) => {
                                return (
                                  <option key={shift._id} value={shift._id}>
                                    {shift?.title}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                      </Row>
                      <Row>
                        <Col className="pr-3" md="12">
                          <Form.Group
                            className="mb-3"
                            controlId="exampleForm.ControlTextarea1"
                          >
                            <Form.Label>Note</Form.Label>
                            <Form.Control
                              as="textarea"
                              rows={3}
                              onChange={handleChange}
                              name="note"
                              value={formData.note}
                            />
                          </Form.Group>
                        </Col>
                      </Row>

                      <Row className="mt-3">
                        <Col className="pr-1" md="12">
                          <CustomizedButton
                            isDisabled={
                              isSubmitting ||
                              [
                                "connected",
                                "calling",
                                "checking",
                                "failed",
                                "connecting",
                              ].includes(props?.io?.call?.status)
                            }
                            status={props?.io?.call?.status}
                            enabledLable="Submit"
                            disabledLable={
                              isSubmitting ? "Submitting..." : "Submit"
                            }
                          />
                        </Col>
                      </Row>

                      {/* <div className="clearfix"></div> */}
                    </Form>
                  )}
                </Card.Body>
              </Card>
            </Col>
          </Row>
        </Modal.Body>
      </Modal>

      {/* Mini Modal */}
      <Modal
        className="modal-mini modal-primary msg-modal"
        // show={true}
        onHide={() => setShowModal(false)}
        backdrop="static"
      >
        <Modal.Body className="d-flex p-0">
          <Row>
            <Col md="12">
              <Card>
                <Card.Header className="d-flex flex-column justify-content-between">
                  <Card.Title as="h4">
                    {" "}
                    Are you sure. Your data will not be saved{" "}
                  </Card.Title>
                  <div className="mt-3">
                    <button
                      onClick={() => handleCloseModal("yes")}
                      className="btn-fill  mr-3 btn btn-info"
                    >
                      Continue
                    </button>
                    <button
                      onClick={() => handleCloseModal("no")}
                      className="btn-fill  btn btn-danger"
                    >
                      Back
                    </button>
                  </div>
                </Card.Header>
              </Card>
            </Col>
          </Row>
        </Modal.Body>
      </Modal>

      {/* End Modal */}
    </>
  );
}

const mapStateToProps = (state) => ({
  io: state.io,
  audio: state.audio,
});

const mapDispatchToProps = (dispatch) => ({
  socketConnect: () => dispatch(socketConnect()),
  setCallModal: (val) => dispatch(setCallModal(val)),
  stopTimer: (reference) => dispatch(stopTimer(reference)),
  setCall: (call) => dispatch(setCall(call)),
  startCall: () => dispatch(startCall()),
});
export default connect(mapStateToProps, mapDispatchToProps)(AdminLayout);
