// use strict
export const unSlug = (str) => {
  return str.replace(/_/g, " ");
};

export const getFirstLetter = (str) => {
  if (str) {
    return str.charAt(0).toUpperCase();
  }
  return;
};

export const getPageCount = (currentPage = 1, limit = 5, index) => {
  if (currentPage > 1) {
    return limit * (currentPage - 1) + 1 + index;
  }
  return index + 1;
};
