import React, { useEffect, useState } from "react";
import { Card, Col } from "react-bootstrap";
import { connect } from "react-redux";
import { retrieveHistory } from "redux/action/socket";
import { sendMessage } from "redux/action/socket";

const MessageBox = (props) => {
  const user = JSON.parse(localStorage.getItem("loggedInUser") || {});
  const [scrollDiv, setScrollDiv] = useState(null);
  const [message, setMessage] = useState("");

  useEffect(() => {
    props.retriveHistory(props.io.curChatUser.id);
  }, [props.io.curChatUser.id]);
  useEffect(() => {
    setScrollDiv(document.getElementById("scrollDiv"));
    scrollDiv?.scrollTo(0, scrollDiv.scrollHeight);
  }, [props.io.histories]);

  if (scrollDiv) {
    scrollDiv?.scrollTo(0, scrollDiv.scrollHeight);
  }
  const handleEnter = (e) => {
    if (e.which == 13 && !e.shiftKey) {
      props.sendMessage(
        {
          from: user._id,
          to: props?.io?.curChatUser?.id,
          body: message,
        },
        props.io.socket
      );
      setMessage("");
      return false;
    } else if (e.shiftKey && e.which == 13) {
      handleChange({ value: e.target.value + "\n" });
    }
  };

  const handleChange = (e) => {
    setMessage(e.target.value);
  };

  const callUser = async (callUser) => {
    props.setCall({
      ...props.call,
      user: props.io.curChatUser,
      showModal: true,
      status: "outgoing",
    });
    props.io.socket.emit("call", {
      from: user._id,
      to: callUser,
    });
  };

  let content = props?.io?.curChatUser?.id ? (
    <Col md="8">
      <Card className="strpied-tabled-with-hover">
        <Card.Header className="chatbox-header">
          <Card.Title>
            <div className="d-flex align-items-center py-1">
              <div className="position-relative">
                <div className="avatar-box bg-light-danger">
                  <span className="avatar-label">S</span>
                </div>
              </div>
              <div className="flex-grow-1 ml-3">
                <span className="chat-username-sm">
                  {props?.io?.curChatUser?.firstname ||
                    props?.io?.curChatUser?.username}
                </span>
                <div className="text-muted small">
                  <em> {props?.io?.curChatUser?.onlineStatus} </em>
                </div>
              </div>
              <div>
                <button
                  type="button"
                  onClick={() => {
                    callUser(props?.io?.curChatUser?.id);
                  }}
                  className="mr-2 voice-call-btn d-md-inline-block btn btn-info"
                >
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="24"
                    height="24"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    className="feather"
                  >
                    <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"></path>
                  </svg>
                </button>

                <button
                  type="button"
                  className="mr-2 more-btn d-md-inline-block btn btn-info"
                >
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="24"
                    height="24"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    className="feather"
                  >
                    <circle cx="12" cy="12" r="1"></circle>
                    <circle cx="19" cy="12" r="1"></circle>
                    <circle cx="5" cy="12" r="1"></circle>
                  </svg>
                </button>
              </div>
            </div>
          </Card.Title>
        </Card.Header>
        <Card.Body className="conversation-text">
          <div id="scrollDiv" className="scroll-y height-288">
            {/* received */}
            {props.io &&
              props.io.histories &&
              Array.isArray(props.io.histories) &&
              props.io.histories?.map((msg, i) => {
                return msg.body || msg.message ? (
                  <div
                    key={i}
                    className={`d-flex justify-content-${
                      (msg.from || msg.sender) == user._id ? "end" : "start"
                    } mb-5`}
                  >
                    <div
                      className={`d-flex flex-column align-items-${
                        (msg.from || msg.sender) == user._id ? "end" : "start"
                      }`}
                    >
                      <div className="d-flex align-items-center mb-2">
                        <div className="avatar-box bg-light-danger">
                          <span className="avatar-label">S</span>
                        </div>
                        <div className="ml-3">
                          <span className="chat-username">
                            {(msg.from || msg.sender) == user._id
                              ? user.firstname || user.username
                              : props?.io?.curChatUser?.firstname ||
                                props?.io?.curChatUser?.username}
                          </span>
                        </div>
                      </div>
                      {/* Message Box */}
                      <div
                        className={`p-2 rounded bg-light-${
                          (msg.from || msg.sender) == user._id
                            ? "info"
                            : "primary"
                        } text-dark fw-semibold mw-lg-400px text-start`}
                      >
                        {msg.body || msg.message}
                      </div>
                    </div>
                  </div>
                ) : (
                  ""
                );
              })}
          </div>
        </Card.Body>

        <Card.Footer className="send-help">
          <textarea
            className="form-control form-control-flush mb-3"
            rows="2"
            name="message"
            onChange={handleChange}
            onKeyDown={handleEnter}
            placeholder="Type a message"
            value={message}
            id="message"
            spellCheck="false"
          ></textarea>
          <div className="d-flex justify-content-end">
            <button
              id="sendbtn"
              onClick={() => {
                props.sendMessage(
                  {
                    from: user._id,
                    to: props?.io?.curChatUser?.id,
                    body: message,
                  },
                  props.io.socket
                );
                setMessage("");
              }}
              onChange={handleChange}
              className="btn btn-brand"
              name="message"
              type="submit"
            >
              Send
            </button>
          </div>
        </Card.Footer>
      </Card>
    </Col>
  ) : (
    "Select a user to chat with"
  );
  return content;
};

const mapStateToProps = (state) => ({
  io: state.io,
});

const mapDispatchToProps = (dispatch) => ({
  sendMessage: (msg, socket) => dispatch(sendMessage(msg, socket)),
  retriveHistory: (id) => dispatch(retrieveHistory(id)),
});
export default connect(mapStateToProps, mapDispatchToProps)(MessageBox);
