import React, { useContext, useEffect, useState } from "react";
import { Redirect } from "react-router-dom";
import { Card, Container, Row, Col, Modal, Button } from "react-bootstrap";
import auth from "utility/auth";
import { connect } from "react-redux";
import MessageBox from "./ChatComponent/MessageBox";

import { getFirstLetter } from "helpers";
import { setCurChatUser } from "redux/action/socket";
import { getRosters } from "redux/action/socket";
const Chat = (props) => {
  const user = JSON.parse(localStorage.getItem("loggedInUser") || {});

  useEffect(() => {
    props.getRosters(user._id);
  }, []);

  const handleCurChatUser = async (user) => {
    props.setCurChatUser(
      {
        username: user?.username,
        firstname: user?.firstname,
        lastname: user?.lastname,
        middleName: user?.middleName,
        gender: user?.gender,
        email: user.email,
        id: user._id,
        onlineStatus: user.onlineStatus,
      },
      props?.io?.socket,
      user?.lastMessage
    );
  };

  const getSeenClass = (u, myId) => {
    // if message is not seen and it is sent to me
    if (
      !u?.lastMessage?.seen &&
      (u?.lastMessage?.to || u?.lastMessage?.receiver) == myId
    ) {
      return "bold";
    }
    return "semibold";
  };
  // rosters
  let rosterContents = (
    <>
      {props.io?.rosters.map((u, index) => {
        return (
          <div key={index} className="d-flex user-list py-2">
            <div className="info-section d-flex">
              <div className="avatar-box bg-light-danger">
                <span className="avatar-label">
                  {getFirstLetter(u?.firstname || u?.username)}
                </span>
                <div
                  className={`avatar-status ${
                    u?.onlineStatus == "Online" ? "bg-success" : "bg-secondary"
                  } start-100 top-100 border-4 h-15px w-15px ms-n2 mt-n2`}
                ></div>
              </div>
              <div onClick={() => handleCurChatUser(u)} className="ml-3">
                <div className="chat-username">
                  {u?.firstname || u?.username}
                </div>

                <div className={`font-weight-${getSeenClass(u, user._id)}`}>
                  {(u?.lastMessage?.sender || u?.lastMessage?.from) == user._id
                    ? "you: "
                    : null}
                  {u?.lastMessage?.body}
                </div>
              </div>
            </div>
          </div>
        );
      })}
    </>
  );

  // contents
  let contents = (
    <>
      <Container fluid>
        <Row>
          {/* user list */}
          <Col md="4">
            <Card className="strpied-tabled-with-hover">
              <Card.Header>
                <Card.Title as="h4"> Messages </Card.Title>
              </Card.Header>
              <Card.Body className="">
                <div className="scroll-y height-450">{rosterContents}</div>
              </Card.Body>
            </Card>
          </Col>
          <MessageBox setCall={props.setCall} call={props.call} />
        </Row>
      </Container>
    </>
  );

  return auth(user).isRole("Facilitator") ||
    auth(user).isUserAllowed("view_chat") ? (
    contents
  ) : (
    <Redirect to="/admin/dashboard" />
  );
};

const mapStateToProps = (state) => ({
  io: state.io,
});

const mapDispatchToProps = (dispatch) => ({
  setCurChatUser: (user, socket, lastMessage) =>
    dispatch(setCurChatUser(user, socket, lastMessage)),
  getRosters: (id) => dispatch(getRosters(id)),
});
export default connect(mapStateToProps, mapDispatchToProps)(Chat);
