const Pagination = ({ itemsCount, pageSize, currentPage, onPageChange }) => {
  let pagesCount = Math.ceil(itemsCount / pageSize);
  if (pagesCount === 1) return null;
  let num = 5;
  let start = currentPage - num > 0 ? currentPage - (num - 1) : 1;
  let end = currentPage + num < pagesCount ? currentPage + num : pagesCount;

  let pages = [];
  for (let i = start; i <= end; i++) {
    pages.push(i);
  }
  let content = "";
  if (pagesCount > num) {
    content = (
      <nav>
        <ul className="pagination justify-content-end">
          {currentPage > 1 && (
            <>
              <li onClick={() => onPageChange(1)} className="page-item">
              <button className="page-link" aria-label="Next">
                  <span aria-hidden="true">
                    <i className="fas fa-angle-double-left"></i>
                  </span>
                </button>
              </li>
              <li
                onClick={() => onPageChange(currentPage - 1)}
                className="page-item"
              >
                <button className="page-link" aria-label="Next">
                  <span aria-hidden="true">
                    <i className="fas fa-angle-left"></i>
                  </span>
                </button>
              </li>
            </>
          )}
          {pages.map((page) => (
            // <li onClick={() => onPageChange(page)} className="page-item">
            //   {page}
            // </li>
            <li onClick={() => onPageChange(page)} className="page-item">
              <button className="page-link">{page}</button>
            </li>
          ))}
          {currentPage < pagesCount && (
            <>
              <li className="page-item" onClick={() => onPageChange(currentPage + 1)}>
              <button className="page-link" aria-label="Next">
                  <span aria-hidden="true">
                    <i className="fas fa-angle-right"></i>
                  </span>
                </button>
              </li>
              <li className="page-item" onClick={() => onPageChange(pagesCount)}>
              <button className="page-link" aria-label="Next">
                  <span aria-hidden="true">
                    <i className="fas fa-angle-double-right"></i>
                  </span>
                </button>
              </li>
            </>
          )}
        </ul>
      </nav>
    );
  }

  return content;

};

export default Pagination;
