import { twoDigit } from "helpers/string.helper";
import CONSTANTS from "redux/constants";
import io from "socket.io-client";
import store from "../store";
import { axios } from "utility/httpreq";
import { playAudio } from "helpers/audio.helper";
import { stopAudio } from "helpers/audio.helper";

let status = {
  connecting: "connecting...",
  connected: "connected",
  disconnected: "disconnected",
  disconnecting: "disconnecting...",
  failed: "failed",
};
export const socketConnect = () => (dispatch) => {
  const socket = io.connect(process.env.REACT_APP_BASE_URL, {
    extraHeaders: {
      "x-access-token": localStorage.getItem("token"),
    },
  });
  dispatch({
    type: CONSTANTS.SOCKET_STATUS,
    payload: {
      connected: false,
      connecting: true,
    },
  });
  socket.on("connect", () => {
    dispatch({
      type: CONSTANTS.SOCKET_CONNECT,
      payload: {
        socket,
        connected: true,
        connecting: false,
      },
    });
  });

  socket.on("disconnect", () => {
    dispatch({
      type: CONSTANTS.SOCKET_DISCONNECT,
      payload: {
        socket: null,
        connected: false,
        connecting: false,
      },
    });
  });

  socket.on("receive-msg", (data) => {
    if (window?.location?.pathname === "/admin/chat") {
      // check if message is from current chat user then emit seen message
      if (data.from || data.sender == store.getState()?.io?.curChatUser?.id) {
        socket.emit("messageSeen", data);
      }
      // check roster if user is not in roster then add user to roster
      const rosters = store.getState()?.io?.rosters;
      if (rosters) {
        // const roster = rosters.find((roster) => roster.id == data.from);

        // if (!roster) {
        dispatch(
          getRosters(JSON.parse(localStorage.getItem("loggedInUser"))?._id)
        );
        // }
      }
    }

    dispatch({
      type: CONSTANTS.RECEIVE_MESSAGE,
      payload: data,
    });
  });
};

export const setCurChatUser = (user, socket, lastMessage) => (dispatch) => {
  if (lastMessage && user != lastMessage.from) {
    socket.emit("messageSeen", { ...lastMessage, seen: Date.now() });
  }

  dispatch({
    type: CONSTANTS.SET_CHAT_USER,
    payload: user,
  });
};

export const getRosters = (id) => async (dispatch) => {
  // const response = await axios(true).get(`/api/user/list`);
  const response = await axios(true).get(`/api/user/roster/${id}`);
  if (Array.isArray(response.data.data)) {
    dispatch({
      type: CONSTANTS.GET_ROSTER,
      payload: { rosters: response.data.data },
    });
  }
};

export const retrieveHistory = (userId) => async (dispatch) => {
  try {
    if (userId) {
      const res = await axios(true).get(`/api/message/${userId}`);
      dispatch({
        type: CONSTANTS.RETRIEVE_HISTORY,
        payload: res.data.data,
      });
    }
  } catch (err) {
    console.log(err);
  }
};

export const sendMessage = (message, socket) => (dispatch) => {
  if (
    (message.body && message.body.trim()) ||
    (message.message && message.from && message.to)
  ) {
    if (!socket.connected) {
      axios(true).post("/api/message/send", message);
    }
    socket.emit("send-msg", message);
    dispatch({
      type: CONSTANTS.SEND_MESSAGE,
      payload: message,
    });
  }
};

export const startTimer = (start) => (dispatch) => {
  const getTimeRemaining = () => {
    const total = Date.now() - start;
    const s = Math.floor(total / 1000);
    const seconds = Math.floor(s % 60);
    const minutes = Math.floor((s / 60) % 60);
    const hours = Math.floor((s / 3600) % 24);
    // setTimer(`${twoDigit(hours)}:${twoDigit(minutes)}:${twoDigit(seconds)}`);
    dispatch({
      type: CONSTANTS.SET_CALL_DURATION,
      payload: {
        duration: `${twoDigit(hours)}:${twoDigit(minutes)}:${twoDigit(
          seconds
        )}`,
        totalTime: total,
      },
    });
  };
  const reference = setInterval(() => {
    getTimeRemaining();
  }, 1000);

  dispatch({
    type: CONSTANTS.SET_CALL,
    payload: { start: start, reference },
  });
};

export const stopTimer = (reference) => (dispatch) => {
  if (reference) {
    clearInterval(reference);
    dispatch({
      type: CONSTANTS.SET_CALL,
      payload: { reference: null, start: null },
    });
  }
};

export const setCallModal = (val) => (dispatch) => {
  dispatch({
    type: CONSTANTS.SET_CALL_MODAL,
    payload: val,
  });
};
export const startCall = () => (dispatch) => {
  dispatch({
    type: CONSTANTS.SET_CALL_MODAL,
    payload: true,
  });
};

export const setCall = (val) => (dispatch) => {
  dispatch({
    type: CONSTANTS.SET_CALL,
    payload: val,
  });
};
