import CONSTANTS from "redux/constants";
import Outgoing from "../../sounds/outgoing.mp3";
import Incoming from "../../sounds/incoming.wav";
import Connected from "../../sounds/connected.mp3";
import { Howl } from "howler";

export const audioReducer = (
  state = {
    incoming: new Howl({
      src: [Incoming],
      loop: true,
    }),
    outgoing: new Howl({
      src: [Outgoing],
      loop: true,
    }),
    connected: new Howl({
      src: [Connected],
      loop: false,
    }),
  },
  action
) => {
  switch (action.type) {
    case CONSTANTS.PLAY_OUTGOING:
      state.outgoing.play();
      state.outgoing.loop = true;
      return state;
    case CONSTANTS.PLAY_INCOMING:
      state.incoming.play();
      state.incoming.loop = true;
      return state;
    case CONSTANTS.PLAY_CONNECTED:
      state.connected.play();
      return state;
    case CONSTANTS.STOP_OUTGOING:
      state.outgoing.pause();
      state.outgoing.currentTime = 0;
      state.outgoing.loop = false;
      state.outgoing.load();
      return state;
    case CONSTANTS.STOP_INCOMING:
      state.incoming.pause();
      state.incoming.currentTime = 0;
      state.incoming.loop = false;
      state.incoming.load();
      return state;
    case CONSTANTS.STOP_CONNECTED:
      state.connected.pause();
      state.connected.currentTime = 0;
      state.connected.loop = false;
      state.connected.load();
      return state;

    default:
      return state;
  }
};
