
export const isSelected = function (queryData, curData) {
  //if query is array
  if (Array.isArray(queryData)) {
    if (queryData.indexOf(curData) >= 0) {
      return true;
    }

    return false;
  }
  //if query isn't array
  if (queryData == curData) {
    return true;
  }
  return false;
};
