import CustomizedButton from "components/common/CustomizedButton";
import React, { useEffect, useState } from "react";
import { Card, Form, Container, Row, Col } from "react-bootstrap";
import { connect } from "react-redux";
import { useHistory } from "react-router";
import { axios } from "utility/httpreq";
import notify from "utility/notify";
let defaultFormData = {
  title: "",
  subtitle: "",
  cardBody: "",
  body: "",
  email: "",
  thumbnail: "",
  youtubeVideoId: "",
};
const AddUser = () => {
  const [isLogging, setIsLogging] = useState(false);
  const [info, setInfo] = useState(defaultFormData);

  async function handleSubmit(e) {
    e.preventDefault();
    setIsLogging(true);
    const formData = new FormData();

    for (let key in info) {
      formData.append(key, info[key]);
    }
    try {
      const blog = await axios(true, true).post("/api/blog/add", formData);
      setIsLogging(false);
      setInfo(defaultFormData);
      notify.showSuccess("Blog added successfully.");
    } catch (err) {
      setIsLogging(false);
      notify.showError(err.response);
    }
  }
  const handleChange = (e) => {
    const { name, value, type, files } = e.target;

    if (type == "file") {
      return setInfo({ ...info, [name]: files[0] });
    }

    setInfo({ ...info, [name]: value });
  };
  return (
    <>
      <Container fluid>
        <Row>
          <Col md="8">
            <Card>
              <Card.Header>
                <Card.Title as="h4"> Add Blog</Card.Title>
              </Card.Header>
              <Card.Body>
                <Form onSubmit={handleSubmit}>
                  <Row>
                    <Col className="pr-3 pl-3" md="12">
                      <Form.Group>
                        <label>Title</label>
                        <Form.Control
                          placeholder="Title"
                          type="text"
                          name="title"
                          value={info.title}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row>

                  <Row>
                    <Col className="pl-3" md="12">
                      <Form.Group>
                        <label>Sub title</label>
                        <Form.Control
                          placeholder="Subtitle"
                          type="text"
                          name="subtitle"
                          value={info.subtitle}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row>
                  {/* <Row>
                    <Col className="pl-3" md="12">
                      <Form.Group>
                        <label>Video Url</label>
                        <Form.Control
                          placeholder="Your video url"
                          type="text"
                          name="youtubeVideoId"
                          value={info?.youtubeVideoId}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row> */}

                  <Row>
                    <Col className="pr-3" md="12">
                      <Form.Group>
                        <label htmlFor="shortDescription">
                          Short Description
                        </label>
                        <textarea
                          className="form-control form-control-flush mb-3"
                          rows="2"
                          id="shortDescription"
                          name="cardBody"
                          value={info.cardBody}
                          onChange={handleChange}
                          placeholder="Short Description"
                          spellCheck="false"
                        ></textarea>
                      </Form.Group>
                    </Col>
                  </Row>

                  <Row>
                    <Col className="pr-3" md="12">
                      <Form.Group>
                        <label htmlFor="longDescription">
                          Long Description
                        </label>
                        <textarea
                          className="form-control form-control-flush mb-3"
                          rows="2"
                          name="body"
                          value={info.body}
                          onChange={handleChange}
                          placeholder="Long Description"
                          id="longDescription"
                          spellCheck="false"
                        ></textarea>
                      </Form.Group>
                    </Col>
                  </Row>

                  <Row>
                    <Col className="pr-1" md="12">
                      <Form.Group>
                        <label htmlFor="longDescription">Thumbnail</label>
                        <Form.Control
                        className="p-2"
                          type="file"
                          name="thumbnail"
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row>

                  {info?.thumbnail ? (
                    <Row className="mt-3">
                      <Col className="pr-1" md="12">
                        <figure>
                          <img
                            src={URL.createObjectURL(info?.thumbnail)}
                            className="img-fluid"
                            alt={info?.thumbnail.name}
                          />
                        </figure>
                      </Col>
                    </Row>
                  ) : null}

               
                  {/* <Row>
                    <Col className="pr-1" md="12">
                   

                      <iframe
                        width="560"
                        height="315"
                        src={`https://www.youtube.com/embed/${
                          info?.youtubeVideoId || ""
                        }`}
                        title="YouTube video player"
                        frameborder="0"
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                        allowfullscreen
                      ></iframe>
          
                    </Col>
                  </Row> */}
       

                  <Row className="mt-3">
                    <Col className="pr-1" md="12">
                      {/* <Button
                        className="btn-fill pull-right"
                        type="submit"
                        variant="info"
                      >
                        Submit
                      </Button> */}
                      <CustomizedButton
                        isDisabled={isLogging}
                        classNames="btn-fill pull-right"
                      />
                    </Col>
                  </Row>

                  <div className="clearfix"></div>
                </Form>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
};

// export default AddUser;

const mapStateToProps = (state) => ({});

const mapDispatchToProps = (dispatch) => ({});
export default connect(mapStateToProps, mapDispatchToProps)(AddUser);
