export const generateUrl = (url, query = {}, newQuery = {}) => {
  let allQuery = { ...query, ...newQuery };
  if (Object.keys(allQuery).length > 0) {
    url += "?";
  }
  Object.keys(allQuery).forEach((key) => {
    let value = allQuery[key];
    if (!allQuery[key]) {
      return;
    }
    if (Array.isArray(allQuery[key])) {
      value = value.reduce((acc, cur) => acc + `&${key}=${cur}`);
    }
    url += `&${key}=${value}`;
  });
  return url;
};

export const parseQueryToJson = (query) => {
  return query
    ? (/^[?#]/.test(query) ? query.slice(1) : query)
        .split("&")
        .reduce((params, param) => {
          let [key, value] = param.split("=");
          params[key] = value
            ? decodeURIComponent(value.replace(/\+/g, " "))
            : "";
          return params;
        }, {})
    : {};
};
