import React, { useState, useEffect } from "react";
import { Card, Table, Container, Row, Col } from "react-bootstrap";

import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";

import { Link, Redirect, useHistory } from "react-router-dom";

import auth from "utility/auth";

import useFetchData from "hooks/useFetchData";
import { formatTableData } from "helpers/string.helper";
import { formatDate } from "helpers/date.helper";
import { parseQueryToJson, generateUrl } from "helpers/url.helper";
import Pagination from "components/common/Pagination";
import { getPageCount } from "helpers";

const CallLogs = () => {
  const history = useHistory();
  const [filter, setFilter] = useState(
    parseQueryToJson(history.location.search || "")
  );

  const { data, loading } = useFetchData(
    generateUrl("/api/call-log/list", filter)
  );

  const onPageChange = (page) => {
    setFilter({ ...filter, page });
    console.log("current page is", page)
    history.push(generateUrl("/admin/calllog", { ...filter, page }));
  };
  const user = JSON.parse(localStorage.getItem("loggedInUser"));
  let content = loading ? (
    <p>Loading....</p>
  ) : (
    <>
      <Container fluid>
        <Row>
          <Col md="12">
            <Card className="strpied-tabled-with-hover">
              <Card.Header>
                <Card.Title as="h4"> Call Logs </Card.Title>
              </Card.Header>
              <Card.Body
                style={{
                  overflow: "auto",
                }}
                className="table-full-width table-responsive px-0"
              >
                <Table className="table-hover table-striped">
                  <thead>
                    <tr>
                      <th className="border-0">SN</th>
                      <th className="border-0">Date</th>
                      <th className="border-0">Call From</th>
                      <th className="border-0">Call To</th>
                      <th className="border-0">Shift</th>
                      <th className="border-0">CallType</th>
                      <th className="border-0">Caller</th>
                      <th className="border-0">Duration</th>
                      <th className="border-0">Marital Status</th>
                      <th className="border-0">Occupation</th>
                      <th className="border-0">Referral From</th>
                      <th className="border-0">Referral To</th>
                      <th className="border-0">Relation</th>
                      <th className="border-0">Service</th>
                      <th className="border-0">Sucide</th>
                      <th className="border-0">Support Through</th>
                      <th className="border-0">Vulnerability</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data?.data?.map((item, index) => (
                      <tr key={index}>
                        <td> {getPageCount(filter?.page, 5, index)} </td>
                        <td>{formatDate(item.date)}</td>
                        <td> {item?.callFrom?.username || "-"}</td>
                        <td> {item?.callTo?.username || "-"} </td>
                        <td> {formatTableData(item?.shift?.title)} </td>
                        <td>{item?.callType || "-"}</td>
                        <td>{formatTableData(item?.caller)}</td>
                        <td>{formatTableData(item?.duration)}</td>
                        <td>{formatTableData(item?.maritalStatus)}</td>
                        <td>{formatTableData(item?.occupation)}</td>
                        <td>{formatTableData(item?.referralFrom)}</td>
                        <td>{formatTableData(item?.referralTo)}</td>
                        <td>{formatTableData(item?.relation)}</td>
                        <td>{formatTableData(item?.service)}</td>
                        <td>{formatTableData(item?.sucide)}</td>
                        <td>{formatTableData(item?.supportThrough)}</td>
                        <td>{formatTableData(item?.vulnerability)}</td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
                <Pagination
                  itemsCount={data?.count || 0}
                  pageSize={5}
                  currentPage={filter?.page || 1}
                  onPageChange={onPageChange}
                />
              </Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );

  return content;
  // if (auth(user)?.isRole("Admin") || auth(user)?.isUserAllowed("view_user")) {
  //   return content;
  // } else {
  //   return <Redirect to="/admin/dashboard" />;
  // }
};
export default CallLogs;
